/* Generated by Trae Work */
/* 我的学习：番茄钟 / 看板（ECharts，本地库）/ Anki 导出 / 打卡 */
"use strict";
(function () {
  /* ================= 番茄钟 ================= */
  const pomoState = { running: false, left: 25 * 60, timer: null, target: null, len: 25 };
  function pomoTargets() {
    const opts = [];
    /* 已选自考科目 */
    Store.get("zk_subjects", []).forEach(code => {
      opts.push({ value: "subject:zikao:" + code, label: `[自考] ${subjectName(code)}` });
    });
    /* 考研科目 */
    ["408-ds", "408-org", "408-os", "408-net"].forEach(c => {
      opts.push({ value: "subject:kaoyan:" + c, label: `[考研] ${subjectName(c)}` });
    });
    opts.push({ value: "subject:kaoyan:数二", label: "[考研] 数学（二）" });
    opts.push({ value: "subject:kaoyan:英二", label: "[考研] 英语（二）" });
    /* 今日游标任务（完成番茄钟即自动完成该任务并推进游标） */
    try {
      (window.CursorAPI ? CursorAPI.todayUnitBlocks() : []).forEach(b => {
        opts.push({ value: "unit:" + b.id, label: `[今日] ${CursorAPI.poolLabel(b.subject)} · ${b.content_title}` });
      });
    } catch (e) {}
    return opts;
  }
  function renderPomoTargets() {
    const sel = document.getElementById("pomo-target");
    const prev = sel.value;
    const opts = pomoTargets();
    sel.innerHTML = opts.map(o => `<option value="${o.value}">${o.label}</option>`).join("");
    /* 默认选中第一个未完成的今日游标任务（游标前进后自动跟上）；否则保持原选择 */
    const ov = Store.get("block_overrides", {});
    const pending = opts.find(o => o.value.startsWith("unit:") && (!ov[o.value.slice(5)] || ov[o.value.slice(5)].status === "pending"));
    sel.value = pending ? pending.value : (opts.some(o => o.value === prev) ? prev : (opts[0] ? opts[0].value : ""));
  }
  function pomoTick() {
    pomoState.left--;
    if (pomoState.left <= 0) {
      clearInterval(pomoState.timer);
      pomoState.running = false;
      completePomodoro();
    }
    drawPomo();
  }
  function drawPomo() {
    const m = String(Math.floor(pomoState.left / 60)).padStart(2, "0");
    const s = String(pomoState.left % 60).padStart(2, "0");
    document.getElementById("pomo-display").textContent = `${m}:${s}`;
  }
  function completePomodoro() {
    const target = document.getElementById("pomo-target").value;
    const len = +document.getElementById("pomo-len").value || 25;
    const rec = Store.get("pomodoro_log", {});
    const today = fmtDate(new Date());
    (rec[today] = rec[today] || []).push({ target, min: len, at: new Date().toLocaleTimeString() });
    Store.set("pomodoro_log", rec);
    /* 打卡进度自动累加 */
    bumpGoal("pomodoro", 1);
    renderPomoTargets(); /* 游标任务状态可能变化，刷新下拉并选中下一个未完成任务 */
    alert(target.startsWith("unit:")
      ? `番茄钟完成（${len} 分钟），已计入学习统计。\n注意：游标任务需提交章节笔记照片才会完成并推进进度，请回到今日计划点「📷 笔记打卡」。`
      : `番茄钟完成（${len} 分钟），已计入学习统计。`);
    renderStats();
    renderGoals();
  }

  /* ================= 打卡（与课表解耦） ================= */
  function goals() { return Store.get("daily_goals", [{ type: "pomodoro", num: 2 }]); }
  function goalProgress() { return Store.get("goal_progress", {}); }
  function bumpGoal(type, n) {
    const gp = goalProgress();
    const today = fmtDate(new Date());
    if (gp.date !== today) { gp.date = today; gp.counts = {}; }
    gp.counts[type] = (gp.counts[type] || 0) + n;
    Store.set("goal_progress", gp);
  }
  function renderGoals() {
    const gp = goalProgress();
    const today = fmtDate(new Date());
    const counts = gp.date === today ? gp.counts || {} : {};
    const root = document.getElementById("goal-list");
    root.innerHTML = goals().map((g, i) => {
      const label = { pomodoro: "番茄钟", quiz: "选择题", chapter: "自考章节" }[g.type];
      const cur = counts[g.type] || 0;
      const done = cur >= g.num;
      return `<div class="goal-row"><span class="badge ${done ? "ok" : "miss"}">${done ? "已达标" : "进行中"}</span>
        ${label} ≥ ${g.num}（今日 ${cur}）
        <button class="btn small ghost checkin-btn" data-bump="${g.type}" data-i="${i}">+1 打卡</button>
        <button class="btn small ghost" data-del="${i}">删除</button></div>`;
    }).join("") || `<div class="notice empty">尚未设置每日目标。</div>`;
    root.querySelectorAll("[data-bump]").forEach(b => b.addEventListener("click", () => { bumpGoal(b.dataset.bump, 1); renderGoals(); }));
    root.querySelectorAll("[data-del]").forEach(b => b.addEventListener("click", () => {
      const gs = goals(); gs.splice(+b.dataset.del, 1); Store.set("daily_goals", gs); renderGoals();
    }));
  }

  /* ================= 看板 ================= */
  function renderStats() {
    const rec = Store.get("pomodoro_log", {});
    const today = fmtDate(new Date());
    const wrong = Store.get("wrong_book", {});
    const pendingWrong = Object.values(wrong).filter(w => !w.mastered).length;
    const todayPomo = (rec[today] || []).length;
    const totalMin = Object.values(rec).flat().reduce((s, p) => s + (p.min || 0), 0);
    const nSyll = SITE_DATA.zikao.courses.filter(c => c.has_syllabus).length;
    const grid = document.getElementById("stat-grid");
    grid.innerHTML = `
      <div class="stat-card"><div class="num">${todayPomo}</div><div class="lbl">今日番茄钟</div></div>
      <div class="stat-card"><div class="num">${totalMin}</div><div class="lbl">累计专注（分钟）</div></div>
      <div class="stat-card"><div class="num">${pendingWrong}</div><div class="lbl">错题本待复习</div></div>
      <div class="stat-card"><div class="num">${nSyll}/5</div><div class="lbl">自考大纲已收录</div></div>`;
    drawCharts(rec);
  }
  function drawCharts(rec) {
    if (typeof echarts === "undefined") return;
    const style = getComputedStyle(document.documentElement);
    const accent = style.getPropertyValue("--accent").trim();
    const zk = style.getPropertyValue("--zikao").trim();
    const ink = style.getPropertyValue("--ink").trim();
    const muted = style.getPropertyValue("--muted").trim();
    const rule = style.getPropertyValue("--rule").trim();

    /* 本周各科目学习时长（按 track 区分） */
    const wkStart = mondayOf(new Date());
    const zkMap = {}, kyMap = {};
    const zkSel = Store.get("zk_subjects", []);
    Object.entries(rec).forEach(([date, list]) => {
      const d = new Date(date + "T00:00:00");
      if (d < wkStart) return;
      list.forEach(p => {
        if (!p.target) return;
        let track, subj;
        if (p.target.startsWith("unit:")) {
          /* 游标任务：u-<code>-<idx>，按课程归属计入对应 track */
          const pu = (window.CursorAPI && CursorAPI.isUnitId(p.target.slice(5))) ? CursorAPI.parseUnitId(p.target.slice(5)) : null;
          if (!pu) return;
          track = ["数二", "英二", "408"].includes(pu.code) ? "kaoyan" : "zikao";
          subj = pu.code;
        } else if (p.target.startsWith("block:") || p.target.startsWith("rv-")) {
          return; /* 旧课表块与复盘块不计入科目时长 */
        } else {
          const parts = p.target.split(":");
          track = parts[1], subj = parts[2];
        }
        if (track === "zikao") zkMap[subj] = (zkMap[subj] || 0) + (p.min || 0);
        else if (track === "kaoyan") kyMap[subj] = (kyMap[subj] || 0) + (p.min || 0);
      });
    });
    const zkLabels = Object.keys(zkMap), kyLabels = Object.keys(kyMap);
    const c1 = echarts.init(document.getElementById("chart-week"), null, { renderer: "svg" });
    c1.setOption({
      animation: false,
      tooltip: { appendToBody: true },
      legend: { textStyle: { color: muted } },
      grid: { left: 40, right: 16, top: 36, bottom: 30 },
      xAxis: { type: "category", data: [...zkLabels, ...kyLabels], axisLabel: { color: muted, fontSize: 10, interval: 0, rotate: 20 }, axisLine: { lineStyle: { color: rule } } },
      yAxis: { type: "value", name: "分钟", axisLabel: { color: muted }, splitLine: { lineStyle: { color: rule } }, nameTextStyle: { color: muted } },
      series: [
        { name: "自考", type: "bar", data: zkLabels.map(k => zkMap[k]), itemStyle: { color: zk }, barMaxWidth: 26 },
        { name: "考研", type: "bar", data: [...zkLabels.map(() => 0), ...kyLabels.map(k => kyMap[k])], itemStyle: { color: accent }, barMaxWidth: 26 }
      ]
    });
    window.addEventListener("resize", () => c1.resize());

    /* 近 14 天番茄钟趋势 */
    const days = [...Array(14)].map((_, i) => {
      const d = new Date(); d.setDate(d.getDate() - 13 + i);
      return fmtDate(d);
    });
    const counts = days.map(d => (rec[d] || []).length);
    const c2 = echarts.init(document.getElementById("chart-pomo"), null, { renderer: "svg" });
    c2.setOption({
      animation: false,
      tooltip: { appendToBody: true },
      grid: { left: 36, right: 16, top: 24, bottom: 46 },
      xAxis: { type: "category", data: days.map(x => x.slice(5)), axisLabel: { color: muted, fontSize: 10, rotate: 35 }, axisLine: { lineStyle: { color: rule } } },
      yAxis: { type: "value", minInterval: 1, axisLabel: { color: muted }, splitLine: { lineStyle: { color: rule } } },
      series: [{ type: "line", data: counts, itemStyle: { color: ink }, lineStyle: { color: accent }, areaStyle: { color: accent + "22" } }]
    });
    window.addEventListener("resize", () => c2.resize());

    /* 各课游标推进折线（近 14 天已完成单元数，数据源 cursor_history） */
    const pool = (window.CursorAPI ? CursorAPI.coursePool() : []);
    if (pool.length && document.getElementById("chart-cursor")) {
      const ch = Store.get("cursor_history", {});
      const cDays = [...Array(14)].map((_, i) => { const d = new Date(); d.setDate(d.getDate() - 13 + i); return fmtDate(d); });
      const colors = ["#5b8ff9", "#5ad8a6", "#f6bd16", "#e8684a", "#9270ca", "#5d7092"];
      const series = pool.map((code, i) => {
        let last = 0;
        const data = cDays.map(d => {
          const day = ch[d] || {};
          if (day[code] !== undefined) last = day[code];
          return last;
        });
        return { name: CursorAPI.poolLabel(code), type: "line", step: "end", showSymbol: false, data, lineStyle: { color: colors[i % colors.length] }, itemStyle: { color: colors[i % colors.length] } };
      });
      const c3 = echarts.init(document.getElementById("chart-cursor"), null, { renderer: "svg" });
      c3.setOption({
        animation: false,
        tooltip: { appendToBody: true, trigger: "axis" },
        legend: { textStyle: { color: muted }, top: 0 },
        grid: { left: 40, right: 16, top: 40, bottom: 46 },
        xAxis: { type: "category", data: cDays.map(x => x.slice(5)), axisLabel: { color: muted, fontSize: 10, rotate: 35 }, axisLine: { lineStyle: { color: rule } } },
        yAxis: { type: "value", minInterval: 1, name: "已完成单元", axisLabel: { color: muted }, splitLine: { lineStyle: { color: rule } }, nameTextStyle: { color: muted } },
        series
      });
      window.addEventListener("resize", () => c3.resize());
    }
  }

  /* ================= Anki 导出 ================= */
  function download(name, text) {
    const blob = new Blob(["\ufeff" + text], { type: "text/plain;charset=utf-8" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = name;
    a.click();
    URL.revokeObjectURL(a.href);
  }
  function buildAnkiCards(track, codes) {
    /* 卡片背面 = 大纲/笔记章节原文列表 + source_url（原文摘录/链接，非 AI 生成） */
    const lines = [];
    if (track === "zikao") {
      codes.forEach(code => {
        const c = SITE_DATA.zikao.courses.find(x => x.code === code);
        if (!c) return;
        const isSyll = c.has_syllabus && c.chapters;
        const chs = isSyll ? c.chapters : (c.reference_chapters ? c.reference_chapters.chapters : []);
        const url = isSyll ? c.syllabus_url : (c.reference_chapters ? c.reference_chapters.source_url : "");
        const prefix = isSyll ? "官方大纲章节原文" : "公开笔记章节标题";
        chs.forEach((t, i) => {
          const front = `【自考 ${c.code} ${c.name}】官方大纲/笔记中第 ${i + 1} 个章节标题是什么？`;
          const back = `${prefix}：${t}<br>来源：${url}`;
          lines.push(front + "\t" + back);
        });
      });
    } else {
      codes.forEach(code => {
        const s = SITE_DATA.kaoyan.exam408.subjects.find(x => x.code === code);
        if (!s) return;
        const url = SITE_DATA.kaoyan.exam408.syllabus_source.source_url;
        s.chapters.forEach((ch, i) => {
          const front = `【408 ${s.name}】大纲第 ${i + 1} 章「${ch.title}」包含哪些子知识点？`;
          const back = `大纲章节原文摘录：${ch.subs.join("；")}<br>来源：${url}（以当年教育部大纲为准）`;
          lines.push(front + "\t" + back);
        });
      });
    }
    return lines.join("\n");
  }
  function renderAnkiLists() {
    const zk = document.getElementById("anki-zk-list");
    zk.innerHTML = SITE_DATA.zikao.courses.filter(c => c.chapters || c.reference_chapters).map(c =>
      `<label><input type="checkbox" value="${c.code}"> ${c.code} ${c.name}${c.has_syllabus ? "（官方大纲）" : "（参考章节）"}</label>`).join("");
    const ky = document.getElementById("anki-ky-list");
    ky.innerHTML = SITE_DATA.kaoyan.exam408.subjects.map(s =>
      `<label><input type="checkbox" value="${s.code}"> 408 · ${s.name}</label>`).join("");
    document.getElementById("anki-export-zk").addEventListener("click", () => {
      const codes = [...zk.querySelectorAll("input:checked")].map(i => i.value);
      if (!codes.length) return alert("请选择至少一门课程");
      download("anki_zikao_cards.txt", buildAnkiCards("zikao", codes));
    });
    document.getElementById("anki-export-ky").addEventListener("click", () => {
      const codes = [...ky.querySelectorAll("input:checked")].map(i => i.value);
      if (!codes.length) return alert("请选择至少一门科目");
      download("anki_kaoyan_408_cards.txt", buildAnkiCards("kaoyan", codes));
    });
  }

  /* ================= 启动 ================= */
  document.addEventListener("DOMContentLoaded", () => {
    renderPomoTargets();
    drawPomo();
    renderGoals();
    renderStats();
    renderAnkiLists();
    /* 今日计划变化（完成/跳过/游标同步）时刷新番茄钟目标与看板 */
    document.addEventListener("heuprep:plan-changed", () => { renderPomoTargets(); renderStats(); });
    document.getElementById("pomo-start").addEventListener("click", e => {
      if (pomoState.running) {
        clearInterval(pomoState.timer); pomoState.running = false;
        e.target.textContent = "继续专注";
      } else {
        pomoState.left = (+document.getElementById("pomo-len").value || 25) * 60;
        pomoState.running = true;
        e.target.textContent = "暂停";
        pomoState.timer = setInterval(pomoTick, 1000);
      }
    });
    document.getElementById("pomo-reset").addEventListener("click", () => {
      clearInterval(pomoState.timer);
      pomoState.running = false;
      pomoState.left = (+document.getElementById("pomo-len").value || 25) * 60;
      document.getElementById("pomo-start").textContent = "开始专注";
      drawPomo();
    });
    document.getElementById("goal-add").addEventListener("click", () => {
      const gs = goals();
      gs.push({ type: document.getElementById("goal-type").value, num: +document.getElementById("goal-num").value || 1 });
      Store.set("daily_goals", gs);
      renderGoals();
    });
  });
})();
